def days_until_warmer(temps: list[int]) -> list[int]:
    ans, stack = [0] * len(temps), []
    for i, t in enumerate(temps):
        while stack and temps[stack[-1]] < t:
            j = stack.pop()
            ans[j] = i - j
        stack.append(i)
    return ans

perf.naive:
def days_until_warmer(temps: list[int]) -> list[int]:
    ans = [0] * len(temps)
    for i in range(len(temps)):
        for j in range(i + 1, len(temps)):
            if temps[j] > temps[i]:
                ans[i] = j - i
                break
    return ans
